using System.Globalization;
using System.Text.Json;
using Pos.Core.Pricing;

namespace Pos.Tests;

/// <summary>
/// Replays tools/golden-fixtures/pricing-golden.json (generated by running the
/// server's own round2()/pricing formulas, see that folder's README) against
/// Pos.Core.Pricing.PricingMath's decimal port. See Pos.Core/Pricing/Money.cs
/// for why decimal and the server's float rounding are expected to agree.
/// </summary>
public class PricingMathTests
{
    private static readonly JsonDocument Fixture = LoadFixture();

    private static JsonDocument LoadFixture()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Fixtures", "pricing-golden.json");
        return JsonDocument.Parse(File.ReadAllText(path));
    }

    public static IEnumerable<object[]> LineCases()
    {
        foreach (var c in Fixture.RootElement.GetProperty("lineCases").EnumerateArray())
        {
            yield return
            [
                Dec(c, "unitPrice"), Dec(c, "modifiersTotal"), (int)c.GetProperty("quantity").GetDouble(),
                (c.GetProperty("taxRate").ValueKind == JsonValueKind.Null ? (decimal?)null : Dec(c, "taxRate"))!,
                Dec(c, "lineSubtotal"), Dec(c, "taxAmount"), Dec(c, "lineTotal"),
            ];
        }
    }

    [Theory]
    [MemberData(nameof(LineCases))]
    public void PriceLine_matches_server_round2(decimal unitPrice, decimal modifiersTotal, int quantity, decimal? taxRate,
        decimal expectedSubtotal, decimal expectedTax, decimal expectedTotal)
    {
        var line = PricingMath.PriceLine(unitPrice, modifiersTotal, quantity, taxRate);

        Assert.Equal(expectedSubtotal, line.LineSubtotal);
        Assert.Equal(expectedTax, line.TaxAmount);
        Assert.Equal(expectedTotal, line.LineTotal);
    }

    public static IEnumerable<object[]> OrderCases()
    {
        foreach (var c in Fixture.RootElement.GetProperty("orderCases").EnumerateArray())
        {
            var lines = c.GetProperty("lines").EnumerateArray()
                .Select(l => new PricedLine(Dec(l, "unitPrice"), (int)l.GetProperty("quantity").GetDouble(), Dec(l, "lineSubtotal"), Dec(l, "taxAmount"), Dec(l, "lineTotal")))
                .ToList();
            var discounts = c.GetProperty("discounts").EnumerateArray().Select(d => new DiscountInput(Dec(d))).ToList();
            yield return [lines, discounts, Dec(c, "subtotal"), Dec(c, "discountTotal"), Dec(c, "taxTotal"), Dec(c, "total")];
        }
    }

    [Theory]
    [MemberData(nameof(OrderCases))]
    public void ComputeTotals_matches_server_round2(List<PricedLine> lines, List<DiscountInput> discounts,
        decimal expectedSubtotal, decimal expectedDiscountTotal, decimal expectedTaxTotal, decimal expectedTotal)
    {
        var totals = PricingMath.ComputeTotals(lines, discounts);

        Assert.Equal(expectedSubtotal, totals.Subtotal);
        Assert.Equal(expectedDiscountTotal, totals.DiscountTotal);
        Assert.Equal(expectedTaxTotal, totals.TaxTotal);
        Assert.Equal(expectedTotal, totals.Total);
    }

    /// <summary>
    /// Confirmed, not hypothetical: server/services/order.js's round2() rounds this case a
    /// cent low because 0.175 has no exact binary representation, so `lineSubtotal * 0.175`
    /// (a float) lands just under the true half-cent tie before Math.round ever sees it.
    /// Decimal math has no such error — 0.525 really is exactly 0.525, and
    /// round-half-away-from-zero on that is 0.53. See Money.cs for the full writeup and why
    /// this is flagged for the user rather than silently patched on either side.
    /// </summary>
    [Fact]
    public void FloatRoundingDivergence_at_17_5_percent_is_a_known_server_bug()
    {
        var line = PricingMath.PriceLine(unitPrice: 0.5m, modifiersTotal: 0.5m, quantity: 3, taxRate: 0.175m);

        Assert.Equal(0.525m, line.LineSubtotal * 0.175m); // the true value: an exact half-cent tie
        Assert.Equal(0.53m, line.TaxAmount);               // decimal: correct round-half-away-from-zero
        // The live server, run today, returns 0.52 for this exact input — one cent low.
    }

    /// <summary>
    /// The textbook float-tie example (1.005 → 100 vs. 101 cents) — included for the record,
    /// not asserted against the golden set, because it is *not reachable*: ProductVariant.price
    /// is DECIMAL(10,2) in the server schema, so a price with 3 decimal places can never be
    /// stored in the first place. Unlike the 17.5% tax-rate case above, this one is not a bug
    /// to fix — there is no reachable input that hits it.
    /// </summary>
    [Fact]
    public void FloatRoundingDivergence_at_an_unreachable_3dp_price_is_not_a_real_bug()
    {
        var line = PricingMath.PriceLine(unitPrice: 1.005m, modifiersTotal: 0m, quantity: 1, taxRate: null);

        Assert.Equal(1.01m, line.LineSubtotal); // decimal: the true value, rounded correctly
        // The live server, run today, returns 1.00 — but only reachable via a 3dp price,
        // which DECIMAL(10,2) on ProductVariant.price prevents from ever being stored.
    }

    private static decimal Dec(JsonElement element, string property) => Dec(element.GetProperty(property));

    private static decimal Dec(JsonElement element) =>
        decimal.Parse(element.GetRawText(), NumberStyles.Float, CultureInfo.InvariantCulture);
}
